function(container, apiUrl, tables) {
  // 初期化処理
  initializeScreen();

  async function initializeScreen() {
    // 店舗データを読み込んでドロップダウンに設定
    await loadStores();

    // 商品カテゴリを読み込んでチェックボックスを生成
    await loadProductCategories();

    // 日付フィールドのデフォルト値を設定
    setDefaultDates();

    // 季節要因スライダーのイベントリスナー
    setupSeasonalFactorSlider();

    // ボタンのイベントリスナーを設定
    setupEventListeners();
  }

  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      const storeSelect = container.querySelector('#store-select');

      if (stores && stores.length > 0) {
        stores.filter(store => store.有効フラグ).forEach(store => {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        });
      }
    } catch (error) {
      console.error('店舗データの読み込みに失敗しました:', error);
    }
  }

  async function loadProductCategories() {
    try {
      const products = await window.aivicApi.list(2); // 商品マスタ
      const categoryContainer = container.querySelector('#category-checkboxes');

      if (products && products.length > 0) {
        // 商品カテゴリIDでグループ化
        const categories = [...new Set(products.map(p => p.商品カテゴリID))];

        categories.forEach((categoryId, index) => {
          const label = document.createElement('label');
          label.style.display = 'block';
          label.innerHTML = `
            <input type="checkbox" value="${categoryId}" style="margin-right: 8px;">
            カテゴリ ${index + 1}
          `;
          categoryContainer.appendChild(label);
        });
      }
    } catch (error) {
      console.error('商品カテゴリの読み込みに失敗しました:', error);
    }
  }

  function setDefaultDates() {
    const today = new Date();
    const tomorrow = new Date(today);
    tomorrow.setDate(today.getDate() + 1);

    const nextWeek = new Date(today);
    nextWeek.setDate(today.getDate() + 7);

    const lastYear = new Date(today);
    lastYear.setFullYear(today.getFullYear() - 1);

    // 予測対象期間のデフォルト値（明日から1週間後）
    container.querySelector('#prediction-start-date').value = tomorrow.toISOString().split('T')[0];
    container.querySelector('#prediction-end-date').value = nextWeek.toISOString().split('T')[0];

    // 学習データ期間のデフォルト値（過去1年間）
    container.querySelector('#learning-start-date').value = lastYear.toISOString().split('T')[0];
    container.querySelector('#learning-end-date').value = today.toISOString().split('T')[0];
  }

  function setupSeasonalFactorSlider() {
    const slider = container.querySelector('#seasonal-factor');
    const valueDisplay = container.querySelector('#seasonal-value');

    slider.addEventListener('input', function() {
      valueDisplay.textContent = this.value;
    });
  }

  function setupEventListeners() {
    // 天候データ取込ボタン
    container.querySelector('#btn-import-weather').addEventListener('click', async function() {
      await importWeatherData();
    });

    // イベントデータ取込ボタン
    container.querySelector('#btn-import-event').addEventListener('click', async function() {
      await importEventData();
    });

    // AI予測実行ボタン
    container.querySelector('#btn-execute-prediction').addEventListener('click', async function() {
      await executePrediction();
    });
  }

  async function importWeatherData() {
    const statusDiv = container.querySelector('#weather-status');
    statusDiv.textContent = '天候データを取得中...';

    try {
      // 模擬的な天候データ取込処理
      await new Promise(resolve => setTimeout(resolve, 2000));

      // 成功の場合
      if (Math.random() > 0.3) { // 70%の確率で成功
        statusDiv.textContent = '天候データの取込が完了しました';
        statusDiv.style.color = '#28a745';
      } else {
        throw new Error('天候APIへの接続に失敗しました');
      }
    } catch (error) {
      statusDiv.textContent = `天候データの取込に失敗しました: ${error.message}`;
      statusDiv.style.color = '#dc3545';
    }
  }

  async function importEventData() {
    const statusDiv = container.querySelector('#event-status');
    statusDiv.textContent = 'イベントデータを取得中...';

    try {
      // 模擬的なイベントデータ取込処理
      await new Promise(resolve => setTimeout(resolve, 1500));

      // 成功の場合
      if (Math.random() > 0.2) { // 80%の確率で成功
        statusDiv.textContent = 'イベントデータの取込が完了しました';
        statusDiv.style.color = '#28a745';
      } else {
        throw new Error('イベントデータファイルの形式が正しくありません');
      }
    } catch (error) {
      statusDiv.textContent = `イベントデータの取込に失敗しました: ${error.message}`;
      statusDiv.style.color = '#dc3545';
    }
  }

  async function executePrediction() {
    // バリデーション
    const validationError = validateInputs();
    if (validationError) {
      showError(validationError);
      return;
    }

    // 進捗バーを表示
    showProgressBar();

    try {
      // 予測処理の実行（模擬）
      await runPredictionProcess();

      // 成功メッセージを表示
      showSuccess('AI需要予測処理が正常に完了しました。結果は需要予測管理画面で確認できます。');

      // 需要予測管理画面に遷移
      setTimeout(() => {
        window.showScreen('scr-1778591838939');
      }, 2000);

    } catch (error) {
      showError(error.message);
    } finally {
      hideProgressBar();
    }
  }

  function validateInputs() {
    const predictionStartDate = container.querySelector('#prediction-start-date').value;
    const predictionEndDate = container.querySelector('#prediction-end-date').value;
    const storeId = container.querySelector('#store-select').value;
    const selectedModel = container.querySelector('input[name="prediction-model"]:checked');
    const selectedCategories = container.querySelectorAll('#category-checkboxes input[type="checkbox"]:checked');
    const learningStartDate = container.querySelector('#learning-start-date').value;
    const learningEndDate = container.querySelector('#learning-end-date').value;
    const accuracyThreshold = container.querySelector('#accuracy-threshold').value;

    // 予測対象期間のチェック
    if (!predictionStartDate || !predictionEndDate) {
      return '予測対象期間を設定してください。';
    }

    const today = new Date();
    const startDate = new Date(predictionStartDate);
    const endDate = new Date(predictionEndDate);

    if (startDate <= today) {
      return '予測対象期間に過去の日付は選択できません。';
    }

    if (endDate <= startDate) {
      return '予測対象期間の終了日は開始日より後の日付を選択してください。';
    }

    // 店舗選択のチェック
    if (!storeId) {
      return '店舗を選択してください。';
    }

    // 予測モデル選択のチェック
    if (!selectedModel) {
      return '予測モデルを選択してください。';
    }

    // 商品カテゴリ選択のチェック
    if (selectedCategories.length === 0) {
      return '商品カテゴリを1つ以上選択してください。';
    }

    // 学習データ期間のチェック
    if (!learningStartDate || !learningEndDate) {
      return '学習データ期間を設定してください。';
    }

    // 予測精度閾値のチェック
    const threshold = parseInt(accuracyThreshold);
    if (isNaN(threshold) || threshold < 0 || threshold > 100) {
      return '予測精度閾値は0〜100の範囲で入力してください。';
    }

    return null; // バリデーション成功
  }

  async function runPredictionProcess() {
    const progressBar = container.querySelector('#progress-bar');
    const progressText = container.querySelector('#progress-text');

    // 段階的に進捗を更新
    const steps = [
      { progress: 10, message: 'データ収集中...' },
      { progress: 30, message: '外部要因データ取得中...' },
      { progress: 50, message: 'モデル学習中...' },
      { progress: 70, message: '需要予測計算中...' },
      { progress: 90, message: '結果検証中...' },
      { progress: 100, message: '処理完了' }
    ];

    for (const step of steps) {
      await new Promise(resolve => setTimeout(resolve, 800));

      progressBar.style.width = step.progress + '%';
      progressText.textContent = `${step.progress}% - ${step.message}`;

      // ランダムでエラーを発生させる（テスト用）
      if (step.progress === 50 && Math.random() < 0.1) {
        throw new Error('学習データが不足しています。学習データ期間を延長してください。');
      }
    }

    // 予測結果データを保存
    await savePredictionResults();
  }

  async function savePredictionResults() {
    const storeId = container.querySelector('#store-select').value;
    const selectedCategories = Array.from(container.querySelectorAll('#category-checkboxes input[type="checkbox"]:checked')).map(cb => cb.value);
    const predictionStartDate = container.querySelector('#prediction-start-date').value;
    const predictionEndDate = container.querySelector('#prediction-end-date').value;
    const selectedModel = container.querySelector('input[name="prediction-model"]:checked').value;
    const accuracyThreshold = container.querySelector('#accuracy-threshold').value;

    // 模擬的な予測結果データを生成
    const products = await window.aivicApi.list(2); // 商品マスタ
    const targetProducts = products.filter(p => selectedCategories.includes(p.商品カテゴリID));

    for (const product of targetProducts.slice(0, 5)) { // 最初の5商品のみ
      const predictionResult = {
        店舗ID: storeId,
        商品ID: product.商品ID,
        予測対象日: predictionStartDate,
        予測数量: Math.floor(Math.random() * 100) + 10,
        予測精度: Math.floor(Math.random() * 30) + parseInt(accuracyThreshold),
        推奨発注数量: Math.floor(Math.random() * 80) + 5,
        予測モデルバージョン: `${selectedModel}-v1.0`,
        実績数量: null,
        予測ステータス: '完了',
        発注済フラグ: false,
        備考: 'AI自動予測による結果',
        作成者ID: 'system'
      };

      await window.aivicApi.save(9, predictionResult); // 需要予測結果テーブル
    }
  }

  function showProgressBar() {
    const progressContainer = container.querySelector('#progress-container');
    const progressBar = container.querySelector('#progress-bar');
    const progressText = container.querySelector('#progress-text');

    progressContainer.classList.remove('hidden');
    progressBar.style.width = '0%';
    progressText.textContent = '0%';

    hideMessages();
  }

  function hideProgressBar() {
    const progressContainer = container.querySelector('#progress-container');
    progressContainer.classList.add('hidden');
  }

  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');

    const successDiv = container.querySelector('#success-message');
    successDiv.classList.add('hidden');
  }

  function showSuccess(message) {
    const successDiv = container.querySelector('#success-message');
    successDiv.textContent = message;
    successDiv.classList.remove('hidden');

    const errorDiv = container.querySelector('#error-message');
    errorDiv.classList.add('hidden');
  }

  function hideMessages() {
    const errorDiv = container.querySelector('#error-message');
    const successDiv = container.querySelector('#success-message');
    errorDiv.classList.add('hidden');
    successDiv.classList.add('hidden');
  }
}
